","inline":true,"children":[{"text":"s  Z"}]},{"text":", "},{"type":"math","src":"e\in{E}","inline":true,"children":[{"text":"a  E"}]},{"text":" und "},{"type":"math","src":"h\in{H}
","inline":true,"children":[{"text":"h  H"}]},{"text":"."}]},{"type":"p","children":[{"text":""}]},{"type":"p","children":[{"text":"Wenn beispiels­weise die Tupel "},{"type":"math","src":"(1, e, \varepsilon)","inline":true,"children":[{"text":"(1, a, ε)"}]},{"text":" und "},{"type":"math","src":"(1, \varepsilon, \varepsilon)","inline":true,"children":[{"text":"(1, ε, ε)"}]},{"text":" im Definitions­bereich der Übergangs­funktion vorkommen, kann der Automat im Zustand 1 das Zeichen "},{"type":"math","src":"e ","inline":true,"children":[{"text":"e"}]},{"text":" lesen oder nicht lesen; dies ist Nicht­determinismus und bei einem deterministischen Stack­automaten nicht zulässig."}]},{"type":"p","children":[{"text":""}]},{"type":"p","children":[{"text":"Der im vorigen Beispiel betrachtete Stackautomat ist deterministisch."}]}],"id":"84e03748-521d-40a1-ac2a-cbd95cc100bb"}],"id":"c9d5d522-3a36-414e-b0d6-f3fc2470fb3d"}},"id":"0047b376-21e2-4680-81b1-d165314ab8bc"}],"id":"d30c1bdd-d7a4-4a3b-9229-eaed1b4d642e"},"exercises":[],"exerciseFolder":{"id":"","title":""},"relatedContent":{"articles":[],"courses":[],"videos":[]},"sources":[]},"id":"6b150cc3-7d2c-4152-8b3c-decd41eda125"}}
